/* Learning block renderer. Pilot only: CFA26-01-01. No private files needed for integrated content. */
(()=>{'use strict';
const D=window.CFA_RATES_DESIGN,R=window.CFA_RECAP.modules[D.module],B=window.CFA_SOURCE_BANK,KEY='cfa26-rates-prototype:v1',LEGACY='cfa26-studyhub:v14';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}};
const write=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));return true}catch{return false}};
let state={mode:'support',last:'rates',attempts:{},visited:{},saved:{},explanations:{},...read(KEY,{})},host=null;
const persist=()=>{if(!write(KEY,state)&&host)host.querySelector('.rp-storage').hidden=false};
const a=(id)=>`#module/${D.module}/learn/${id}`;
const find=(n)=>D.checks.find(q=>q.n===Number(n));
const source=(p,label='View source',sid=D.source)=>`<button type="button" class="rp-textbtn" data-private-read="${esc(sid)}" data-page="${p}">${esc(label)}</button>`;
const src=(p,label='CFAI 2026')=>`<span class="rp-ref">${label} · PDF p. ${p} ${source(p)}</span>`;
const tag=(b)=>`<span class="rp-eyebrow">LOS ${b.los.toUpperCase()}</span>`;
const pct=n=>(n*100).toFixed(2)+'%';
const stored=(b)=>state.explanations[b.id]===true;
const vi=(s,cl='')=>`<p lang="vi" class="rp-vi ${cl}">${esc(s)}</p>`;
const detailVi=(s)=>`<div class="rp-full">${vi(s)}</div>`;
const tex=(markup,label)=>`<math xmlns="http://www.w3.org/1998/Math/MathML" display="block" aria-label="${esc(label)}">${markup}</math>`;
const mi=x=>`<mi>${x}</mi>`,mn=x=>`<mn>${x}</mn>`,mo=x=>`<mo>${x}</mo>`,mrow=x=>`<mrow>${x}</mrow>`,sub=(x,y)=>`<msub>${mi(x)}${mi(y)}</msub>`,frac=(x,y)=>`<mfrac>${mrow(x)}${mrow(y)}</mfrac>`,pow=(x,y)=>`<msup>${mrow(x)}${mrow(y)}</msup>`,par=x=>mo('(')+x+mo(')'),plus=mo('+'),minus=mo('−'),eq=mo('='),one=mn('1'),ri=sub('R','i'),sum=mo('∑'),prod=mo('∏'),growth=par(one+plus+ri),nn=mi('n'),rp=sub('R','P'),debt=sub('V','B'),equity=sub('V','E'),rD=sub('r','D');
const math=[
 mi('r')+mo('≈')+sub('r','RF,real')+plus+mi('IP')+plus+mi('DRP')+plus+mi('LP')+plus+mi('MP'),
 one+plus+sub('r','nom')+eq+par(one+plus+sub('r','real'))+par(one+plus+mi('π')),
 mi('R')+eq+frac(sub('P','1')+minus+sub('P','0')+plus+sub('D','1'),sub('P','0')),
 mi('R')+eq+prod+growth+minus+one,
 '<mover><mi>R</mi><mo>¯</mo></mover>'+eq+frac(sum+ri,nn),
 sub('R','G')+eq+pow(mrow(mo('[')+prod+growth+mo(']')),frac(one,nn))+minus+one,
 sub('X','H')+eq+frac(nn,sum+frac(one,sub('X','i'))),
 sum+frac(sub('CF','t'),pow(par(one+plus+mi('IRR')),mi('t')))+eq+mn('0'),
 sub('R','TW')+eq+prod+growth+minus+one,
 mi('PV')+eq+frac(sub('FV','N'),pow(par(one+plus+frac(sub('r','s'),mi('m'))),mi('m')+mi('N')))+mo(';')+sub('FV','N')+eq+mi('PV')+pow(par(one+plus+frac(sub('r','s'),mi('m'))),mi('m')+mi('N')),
 sub('R','ann')+eq+pow(par(one+plus+mi('HPR')),mi('k'))+minus+one,
 sub('r','cc')+eq+mi('ln')+par(one+plus+mi('R'))+mo(';')+mi('R')+eq+pow(mi('e'),sub('r','cc'))+minus+one,
 '<mtext>Net</mtext>'+eq+'<mtext>Gross</mtext>'+minus+'<mtext>management/admin fees</mtext>',
 sub('R','real')+eq+frac(one+plus+sub('R','nom'),one+plus+mi('π'))+minus+one,
 sub('R','L')+eq+rp+plus+frac(debt,equity)+par(rp+minus+rD),
 sub('R','H')+eq+frac(nn,sum+frac(one,growth))+minus+one,
 sub('R','TW,ann')+eq+pow(mo('[')+prod+par(one+plus+sub('R','year'))+mo(']'),frac(one,mi('N')))+minus+one,
 sub('R','week')+eq+pow(par(one+plus+sub('R','day')),mn('5'))+minus+one+mo(';')+pow(par(one+plus+sub('R','annual')),frac(one,mn('52')))+minus+one,
 sub('R','after-tax')+eq+sub('R','nom')+minus+frac('<mtext>Tax amount</mtext>','<mtext>Initial value</mtext>'),
 sub('R','AT,real')+eq+frac(one+plus+sub('R','after-tax'),one+plus+mi('π'))+minus+one,
 mi('RP')+eq+frac(one+plus+sub('R','asset'),one+plus+sub('R','bill'))+minus+one
];
const placements={1:{f:[],e:[]},2:{f:[0,1],e:[7]},3:{f:[2,3],e:[0,8]},4:{f:[4],e:[]},5:{f:[5],e:[18,1,9]},6:{f:[6,15],e:[2,10]},7:{f:[],e:[]},8:{f:[7],e:[19]},9:{f:[8,16],e:[3]},10:{f:[],e:[11,12,13]},11:{f:[9],e:[14]},12:{f:[10,17],e:[4,15]},13:{f:[11],e:[]},14:{f:[12],e:[17]},15:{f:[18],e:[]},16:{f:[13,19],e:[5]},17:{f:[14,20],e:[6,16]}};
// Explicit solution steps for worked examples where the source provides enough inputs. Others retain the existing solution card and reference.
const stepDetail={
 0:['Determine purchase value: 100 × 34.50 = 3,450.','Determine sale proceeds: 100 × 30.50 = 3,050.','Add cash distributions of 51.55; divide total gain/loss by the initial 3,450.'],
 1:['Convert percentages into growth factors: 1.22, 0.75 and 1.11.','Multiply the factors; take the cube root because there are three equal years.','Subtract one to express the result as an annual return.'],
 2:['Units purchased at EUR10: 100; units at EUR15: 66.6667.','Total amount invested is EUR2,000.','Divide total cash by 166.6667 units.'],
 3:['Use investor viewpoint: −200, −220, +480.','Solve the IRR equation using two annual periods.','For TWR, use year-one HPR 15% and year-two HPR 6.67%; link then take the square root.'],
 4:['Convert the 100-day observation to 365/100 periods per year.','Use 52/4 for the four-week return and 12/3 for the three-month return.','Compound each return using its own exponent; rank the annualized rates.'],
 5:['After tax: 3% × (1 − 20%) = 2.4%.','Convert nominal growth to real growth by dividing 1.024 by 1.02.','Subtract one and express as a percentage.'],
 6:['Total assets EUR10m; debt EUR3m; equity EUR7m.','Asset return minus borrowing cost = 8% − 5% = 3%.','Multiply spread by 3/7 and add the unlevered return.'],
 8:['Convert the annual returns to 1.14, 0.90 and 0.98.','Multiply the three growth factors.','Subtract one for the full three-year return.'],
 14:['Monthly rate = 0.06/12 = 0.005.','Number of periods = 10 × 12 = 120.','Divide CAD5m by the monthly accumulation factor.'],
 18:['Initial wealth = 1. After year 1: 0.50.','After year 2: 0.675; after year 3: 0.85725.','Compare actual terminal wealth to the hypothetical arithmetic-mean path 1.04³ = 1.124864.'],
 19:['Investments use a negative sign; distributions and liquidation use a positive sign.','Enter the four dated net cash flows at equal annual intervals.','Solve for the rate at which the NPV equals zero.']
};
const methods={0:'Holding-period return',1:'Geometric mean',2:'Harmonic mean / total cash ÷ units',3:'IRR and annualized linked return',4:'Compound annualization',5:'Tax adjustment then real return',6:'Leveraged return on equity',7:'Matched comparison of premiums',8:'Linked holding-period return',9:'Arithmetic and geometric mean',10:'Arithmetic and harmonic mean',11:'Linked HPR, means, IRR and NPV',12:'Link quarterly returns',13:'Link the two subperiods and solve IRR per four months',14:'Discount at monthly rate',15:'Annualize each horizon',16:'Real return and geometric risk premium',17:'Gross, linked net and after-tax returns',18:'Link actual factors and compare with AM projection',19:'Cash-flow worksheet IRR'};
function formula(i){const f=R.formulas[i],m=D.formulaInfo[i];return `<section class="rp-formula" id="rp-f-${i}" data-formula="${i}"><div class="rp-small">FORMULA · ${esc(f[0])}</div><div class="rp-math">${tex(math[i],f[1])}</div><p class="rp-symbols">${esc(m[0])}</p><p class="rp-condition"><strong>Use when:</strong> ${esc(m[1])}</p>${detailVi(f[3])}<div class="rp-foot">${src(f[4])}</div></section>`}
function example(i){const x=R.examples[i],steps=stepDetail[i]||[];return `<section class="rp-example" data-example="${i}"><div class="rp-small">WORKED EXAMPLE · Source-based</div><h4>${esc(x[0])}</h4><p>${esc(x[1])}</p>${detailVi(x[2])}<details class="rp-solution"><summary>Show solution</summary><div class="rp-solution-body"><p><strong>Method:</strong> ${esc(methods[i])}</p>${steps.length?`<ol>${steps.map(z=>`<li>${esc(z)}</li>`).join('')}</ol>`:'<p class="rp-muted">Calculation summary; use the linked source for the full table and subparts.</p>'}<div class="rp-calculation">${esc(x[3])}</div><p class="rp-result"><strong>Result:</strong> ${esc(x[4])}</p></div></details><div class="rp-foot">${src(x[5])}</div></section>`}
const tbl=(heads,rows)=>`<div class="rp-tablewrap"><table><thead><tr>${heads.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((c,i)=>i===0?`<th scope="row">${esc(c)}</th>`:`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
function lineSVG(series,{labels,yLabel,min,max,format='num',xLabel='Period'}={}){let w=600,h=245,l=64,r=30,t=15,b=48,iw=w-l-r,ih=h-t-b;let vals=series.flatMap(s=>s.values);let lo=min??Math.min(...vals),hi=max??Math.max(...vals);if(hi===lo){hi++;lo--}const x=i=>l+iw*i/(labels.length-1),y=v=>t+ih*(hi-v)/(hi-lo),fmt=v=>format==='pct'?`${v.toFixed(0)}%`:v.toFixed(2);let ticks=Array.from({length:5},(_,i)=>lo+(hi-lo)*i/4);const lines=series.map((s,i)=>`<polyline fill="none" stroke="${i===0?'#2563eb':'#b7791f'}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" points="${s.values.map((v,j)=>`${x(j)},${y(v)}`).join(' ')}" ${i?'stroke-dasharray="7 5"':''}/>${s.values.map((v,j)=>`<circle cx="${x(j)}" cy="${y(v)}" r="4" fill="${i===0?'#2563eb':'#b7791f'}"><title>${esc(s.name)}: ${fmt(v)}</title></circle>`).join('')}`).join('');return `<div class="rp-chart-y">${esc(yLabel)}</div><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(yLabel)} by ${esc(xLabel)}; ${series.map(s=>esc(s.name)).join(', ')}" class="rp-chart"><title>${esc(yLabel)} by ${esc(xLabel)}</title>${ticks.map(v=>`<line x1="${l}" x2="${w-r}" y1="${y(v)}" y2="${y(v)}" class="rp-gridline"/><text x="${l-10}" y="${y(v)+4}" text-anchor="end">${fmt(v)}</text>`).join('')}${labels.map((a,i)=>`<text x="${x(i)}" y="${h-24}" text-anchor="middle">${esc(a)}</text>`).join('')}<text x="${w/2}" y="${h-3}" text-anchor="middle">${esc(xLabel)}</text>${lines}</svg><div class="rp-legend">${series.map((s,i)=>`<span><i class="${i?'second':''}"></i>${esc(s.name)}</span>`).join('')}</div>`}
function timeline(values,labels){return `<div class="rp-timeline" role="img" aria-label="Cash flows: ${values.join(', ')}">${values.map((v,i)=>`<div><span class="rp-timeline-value">${esc(v)}</span><i></i><small>${esc(labels[i])}</small></div>`).join('')}</div>`}
function simulation(id,title,body,desc){return `<figure class="rp-visual rp-sim" data-sim="${id}"><figcaption><span class="rp-small">INTERACTIVE MODEL · Derived from source</span><strong>${title}</strong></figcaption>${body}<div class="rp-sim-result" aria-live="polite"></div><p class="rp-muted">${desc}</p></figure>`}
const slider=(id,label,min,max,step,val,unit='%')=>`<label class="rp-slider" for="rp-${id}"><span>${label}<output id="rp-${id}-val">${val}${unit}</output></span><input type="range" min="${min}" max="${max}" step="${step}" value="${val}" id="rp-${id}" data-unit="${unit}"></label>`;
function visual(b){switch(b.visual){
 case 'rates':return `<figure class="rp-visual"><figcaption><strong>Two cash flows, one equivalent rate</strong><span class="rp-small">Source illustration · PDF p. 13</span></figcaption>${timeline(['USD 9,500','USD 10,000'],['Today','1 year'])}<div class="rp-visual-note">USD500 compensation ÷ USD9,500 initial value = <strong>5.26%</strong>. The same rate is the required return, discount rate and forgone return.</div></figure>`;
 case 'hpr':return `<figure class="rp-visual"><figcaption><strong>Return decomposition</strong><span class="rp-small">Source illustration · PDF pp. 16–17</span></figcaption>${tbl(['Component','Value','Return on USD100'],[['Price gain','105 − 100','5%'],['Dividend','2','2%'],['Total','7','7%']])}</figure>`;
 case 'means':return `<figure class="rp-visual"><figcaption><strong>Actual wealth versus the arithmetic-mean projection</strong><span class="rp-small">Teaching redraw · Exhibit 2, PDF p. 18 · initial wealth = 1</span></figcaption>${lineSVG([{name:'Actual wealth',values:[1,.5,.675,.85725]},{name:'4% arithmetic-mean projection',values:[1,1.04,1.0816,1.124864]}],{labels:['0','1','2','3'],yLabel:'Wealth per unit invested',min:.4,max:1.2,xLabel:'Year'})}<p class="rp-muted">Returns −50%, +35%, +27% produce a loss despite a positive average observation. The geometric rate reproduces the blue path’s terminal value.</p></figure>`;
 case 'weighted':return `<figure class="rp-visual"><figcaption><strong>Investor cash-flow timeline</strong><span class="rp-small">Exhibit 11 · PDF p. 29 · USD</span></figcaption>${timeline(['−200','−220','+480'],['Start','Year 1','Year 2'])}${tbl(['Measure','What it weights','Annual result'],[['MWR','Dated investor cash flows','9.39%'],['TWR','Linked yearly performance','10.76%']])}<p class="rp-muted">The second investment is made before the weaker year; the two measures answer different questions.</p></figure>`;
 case 'pv':return simulation('pv','What happens to present value as the discount rate changes?',slider('pv-rate','Stated annual rate',0,15,.25,6)+slider('pv-years','Years to payment',1,20,1,10,' yr')+`<label class="rp-field">Compounding frequency <select id="rp-pv-m"><option value="1">Annual</option><option value="2">Semiannual</option><option value="4">Quarterly</option><option value="12" selected>Monthly</option><option value="365">Daily (365)</option></select></label>`,'Fixed future payment CAD5 million. Default inputs reproduce Example 11 (PDF p. 37); other settings are simulations, not additional source questions.');
 case 'annual':return simulation('annual','Annualize a holding-period return',slider('ann-return','Holding-period return',-20,20,.1,6.2)+slider('ann-days','Holding period',30,540,1,100,' days'),'365-day convention. Default inputs reproduce investment A in Example 12 (PDF pp. 38–39). This is a mathematical extrapolation, not a forecast.');
 case 'fees':return `<figure class="rp-visual"><figcaption><strong>From investment performance to purchasing power</strong><span class="rp-small">Calculation sequence · PDF pp. 41–43</span></figcaption><div class="rp-flow"><span>Asset return</span><b>− trading</b><span>Gross</span><b>− management/admin</b><span>Net</span><b>− applicable taxes</b><span>After-tax nominal</span><b>÷ inflation factor*</b><span>After-tax real</span></div><p class="rp-muted">* Apply inflation to the growth factor (1 + return), then subtract 1. This is a conceptual sequence, not a percentage-point subtraction for inflation.</p></figure>`;
 case 'leverage':return simulation('leverage','When does leverage help or hurt?',slider('lev-return','Portfolio return',-15,20,.5,8)+slider('lev-cost','Borrowing cost',0,15,.5,5)+slider('lev-debt','Debt as a share of total assets',0,80,1,30),'Default inputs reproduce the EUR10m illustration (PDF p. 44). The model assumes a fixed borrowing rate and ignores other costs, taxes and margin constraints.');
 default:return '';
}}
function term(i){const x=R.glossary[i];return `<details class="rp-term"><summary>${esc(x[0])}</summary><p>${esc(x[1])}</p>${vi(x[2])}</details>`}function extraConcept(i){if(i===7)return tbl(['Purpose','Mean','Treatment'],[['Typical comparable period','Arithmetic','Use all observations'],['Historical compounded growth','Geometric','Multiply growth factors'],['Equal-money price / positive ratio','Harmonic','Average reciprocals'],['Exclude extreme tails','Trimmed','Remove selected tail observations'],['Retain sample size, reduce tail effect','Winsorized','Replace tails with retained boundaries']]);if(i===2)return tbl(['Premium','Risk compensated'],[['Inflation','Expected loss of purchasing power'],['Default','Failure to make promised payments'],['Liquidity','Price concession needed for quick sale'],['Maturity','Greater rate sensitivity, other things equal']]);if(i===8)return `<details class="rp-detail"><summary>Calculator method · BA II Plus</summary><p>${esc(R.calculator.en)}</p>${detailVi(R.calculator.vi)}${source(R.calculator.page,'View Kaplan calculator instructions',R.calculator.source)}</details>`;if(i===16)return `<details class="rp-detail"><summary>Approximate versus exact real return · SchweserNotes</summary><p>A 7% nominal return and 2% inflation imply an approximate real return of 5%; the exact result is 1.07/1.02 − 1 = 4.90%. The example connects the rate to purchasing power: USD1,070 buys about 1,049 units at USD1.02 per unit.</p>${source(25,'SchweserNotes Book 1 · PDF p. 25','SRC-0134')}</details><details class="rp-detail"><summary>Multiplicative risk-premium convention · SAPP</summary><div class="rp-math">${tex('('+one+plus+sub('R','nom')+')'+eq+par(one+plus+sub('r','RF,real'))+par(one+plus+mi('π'))+par(one+plus+mi('RP')),'Nominal growth factor equals real risk-free factor times inflation factor times risk premium factor')}</div><p>Under this source decomposition, real return has the inflation factor removed. This geometric convention is distinct from the approximate additive rate decomposition in LOS a.</p>${source(25,'SAPP Slides · PDF p. 25','SRC-0018')}</details>`;if(i===17)return `<details class="rp-detail"><summary>Futures exposure and leverage ratio · SAPP</summary><p>When the leverage ratio L is notional exposure divided by the investor’s cash margin, the return on the cash margin before financing and other costs is L times the asset return. This is not the same as applying L to the net borrowing return formula.</p>${source(25,'SAPP Slides · PDF p. 25','SRC-0018')}</details>`;return ''}
function concept(i,b){const r=R.coverageAudit.rows[i],p=placements[i]||{f:[],e:[]};return `<section class="rp-concept" data-concept="${i}" id="rp-c-${i}"><h3>${esc(r.title)}</h3><p>${esc(r.en)}</p>${detailVi(r.vi)}${({3:[0],5:[1],8:[2],9:[3],16:[4],17:[5]}[i]||[]).map(term).join('')}${extraConcept(i)}${p.f.map(formula).join('')}${p.e.map(example).join('')}<details class="rp-detail rp-source-detail"><summary>Source reference · PDF pp. ${r.start}–${r.end}</summary><p>Source-reviewed teaching summary; ${source(r.start,'Open original at the relevant page')}</p></details></section>`}
function question(n){const q=find(n),r=state.attempts[n],saved=!!state.saved[n];return `<section class="rp-question" id="rp-q-${n}" data-question="${n}"><div class="rp-question-head"><span class="rp-small">KNOWLEDGE CHECK · Adapted from CFAI Q${n}</span><button class="rp-textbtn rp-save" data-rp-save="${n}" aria-pressed="${saved}">${saved?'Saved ✓':'Save question'}</button></div><h4>${esc(q.q)}</h4><div class="rp-options" role="group" aria-label="Answer choices">${q.options.map((x,i)=>`<button type="button" class="rp-option ${r?(i===q.correct?'correct':r.choice===i?'wrong':''):''}" data-rp-q="${n}" data-rp-choice="${i}" aria-pressed="${r?.choice===i}" ${r?'disabled':''}><span>${'ABC'[i]}</span><span>${esc(x)}</span></button>`).join('')}</div><div class="rp-feedback" aria-live="polite">${r?feedback(q,r):'<p class="rp-muted">Select one answer to reveal the explanation.</p>'}</div></section>`}
function feedback(q,r){return `<div class="rp-feedback-body ${r.choice===q.correct?'good':'bad'}"><strong>${r.choice===q.correct?'Correct':'Needs review'} · Answer ${'ABC'[q.correct]}</strong><ul>${q.why.map((s,i)=>`<li><strong>${'ABC'[i]}${i===q.correct?' ✓':''}</strong> — ${esc(s)}</li>`).join('')}</ul><details class="rp-feedback-vi"><summary>Vietnamese explanation</summary>${vi(q.vi)}</details><div class="rp-actions">${source(q.p,'Original question')}${source(q.a,'Source solution')}<button class="rp-textbtn" data-rp-retry="${q.n}">Try again</button></div></div>`}
function block(b,i){return `<section class="rp-block ${stored(b)?'rp-expanded-block':''}" id="rp-b-${b.id}" data-rp-block="${b.id}"><div class="rp-block-header"><div>${tag(b)}<h2>${esc(b.title)}</h2></div><span class="rp-block-count">${String(i+1).padStart(2,'0')} / ${D.blocks.length}</span></div><p class="rp-why">${esc(b.why)}</p>${vi(b.support,'rp-support')}<div class="rp-block-tools"><button class="rp-textbtn rp-vtoggle" data-rp-vi="${b.id}" aria-expanded="${stored(b)}">${stored(b)?'Hide Vietnamese':'Show Vietnamese explanation'}</button><a class="rp-textbtn" href="#rp-source" data-rp-jump="rp-source">Source references</a></div>${visual(b)}<div class="rp-concepts ${stored(b)?'rp-expanded':''}">${b.rows.map(j=>concept(j,b)).join('')}</div>${b.id==='means'?`<aside class="rp-warning"><strong>Source note · PDF p. 24</strong><p>${esc(R.notes[0][1])}</p>${detailVi(R.notes[0][2])}</aside>`:''}<aside class="rp-recognition"><h3>Exam recognition</h3><p>${esc(b.recognition)}</p>${b.traps.map(i=>`<p><strong>${esc(R.traps[i][0])}:</strong> ${esc(R.traps[i][1])}</p>${detailVi(R.traps[i][2])}`).join('')}</aside>${b.checks.length?`<div class="rp-checks">${b.checks.map(question).join('')}</div>`:'<p class="rp-muted">The next related learning block includes the source-based knowledge check.</p>'}<div class="rp-takeaway"><strong>Key takeaway</strong><p>${esc(b.takeaway)}</p></div><div class="rp-block-end"><button class="rp-btn" data-rp-read="${b.id}">${state.visited[b.id]?'Reviewed ✓':'Mark as studied'}</button>${i<D.blocks.length-1?`<button class="rp-btn primary" data-rp-jump="rp-b-${D.blocks[i+1].id}">Next block →</button>`:'<button class="rp-btn primary" data-rp-jump="rp-review">Review knowledge checks →</button>'}</div></section>`}
function stats(){const attempted=Object.keys(state.attempts).filter(k=>find(k));const correct=attempted.filter(k=>state.attempts[k].choice===find(k).correct).length;const needs=attempted.length-correct;return {attempted:attempted.length,correct,needs,studied:Object.keys(state.visited).filter(k=>state.visited[k]).length,saved:Object.keys(state.saved).filter(k=>state.saved[k]).length}}
function review(){const s=stats(),ids=D.checks.filter(q=>state.saved[q.n]||(state.attempts[q.n]&&state.attempts[q.n].choice!==q.correct));return `<section id="rp-review" class="rp-final"><h2>Review</h2><p class="rp-muted">Based on your latest submitted answer to each knowledge check, not on page views.</p><div class="rp-metrics"><div><strong>${s.attempted}/13</strong><span>Answered</span></div><div><strong>${s.attempted?Math.round(s.correct/s.attempted*100)+'%':'—'}</strong><span>Accuracy</span></div><div><strong>${s.needs}</strong><span>Needs review</span></div></div><h3>Saved & incorrect checks</h3>${ids.length?`<ul class="rp-review-list">${ids.map(q=>`<li><button class="rp-textbtn" data-rp-jump="rp-q-${q.n}">Q${q.n} · ${esc(q.q)}</button><span>${state.saved[q.n]?'Saved ':''}${state.attempts[q.n]&&state.attempts[q.n].choice!==q.correct?'Needs review':''}</span></li>`).join('')}</ul>`:'<p class="rp-empty">No saved or incorrect checks yet. Answer a knowledge check or save it to review here.</p>'}<h3>Review by LOS</h3>${tbl(['LOS','Practice','Status'],D.objectives.map((x,i)=>{const l='abcde'[i],bs=D.blocks.filter(b=>b.los===l),qs=bs.flatMap(b=>b.checks),done=qs.filter(n=>state.attempts[n]),ok=done.filter(n=>state.attempts[n].choice===find(n).correct);return [l.toUpperCase(),`${ok.length}/${qs.length} correct`,done.some(n=>state.attempts[n].choice!==find(n).correct)?'Needs review':done.length===qs.length?'Practiced':done.length||bs.some(b=>state.visited[b.id])?'Learning':'Not started']}))}<p class="rp-muted">“Practiced” does not mean mastered. Full question-bank practice is available separately.</p><a class="rp-btn primary" href="#module/${D.module}/questions/0">Practice original source questions →</a></section>`}
function sourcePanel(){return `<section id="rp-source" class="rp-final"><h2>Source references & coverage</h2><p>Primary: CFA Program Curriculum 2026, Volume 1 Quantitative Methods, Learning Module 1, PDF pp. 11–52. English teaching summaries and Vietnamese support are interpretations of the source; visualizations and adapted checks are labeled.</p><div class="rp-actions">${source(11,'Read CFAI Curriculum')}${source(14,'Read SchweserNotes','SRC-0134')}${source(4,'Read SAPP Slides','SRC-0018')}${source(1,'Read Quant Mindmap','SRC-0010')}<a class="rp-btn" href="#library/01">Quantitative Methods Library</a><a class="rp-btn" href="#module/${D.module}/learn/legacy">Previous full lesson</a></div><details class="rp-detail"><summary>Coverage map · 18 topic groups, 21 formulas, 20 example cards</summary>${tbl(['LOS','Topic','PDF pages'],R.coverageAudit.rows.map(r=>[r.los.toUpperCase(),r.title,r.start+'–'+r.end]))}</details><details class="rp-detail"><summary>17 Exhibit references</summary><ul>${R.coverageAudit.exhibits.map(x=>`<li>Exhibit ${x.number} — ${esc(x.title)} ${source(x.page,'PDF p. '+x.page)}</li>`).join('')}</ul></details><details class="rp-detail"><summary>Source notes & limitations</summary>${R.notes.map(x=>`<p><strong>${esc(x[0])}</strong> · ${esc(x[1])}</p>${detailVi(x[2])}`).join('')}<p>All prior data remain available. This pilot is not an exhaustive line-by-line comparison of all secondary sources, all exhibit cells or all examples' subparts. Original materials remain private and optional. SchweserNotes PDF pp. 14–28, SAPP Slides PDF pp. 4–33 and the Quant Mindmap were reopened for a topic-level cross-check; their distinct numerical illustrations and every cell have not yet been exhaustively mapped.</p></details><details class="rp-detail"><summary>Terminology glossary</summary>${R.glossary.map(x=>`<p><strong>${esc(x[0])}</strong> — ${esc(x[1])}</p>${vi(x[2],'rp-support')}`).join('')}</details></section>`}
function status(){const s=stats();host.querySelector('.rp-progress-text').textContent=`${s.studied}/8 blocks studied · ${s.attempted}/13 checks`;host.querySelector('.rp-progress-fill').style.width=(s.studied/8*100)+'%';host.querySelector('.rp-progress-track').setAttribute('aria-valuenow',String(s.studied));const summary=host.querySelector('#rp-review');if(summary)summary.outerHTML=review();host.querySelectorAll('.rp-toc button[data-rp-jump]').forEach(btn=>{const b=D.blocks.find(x=>'rp-b-'+x.id===btn.dataset.rpJump);if(b){btn.querySelector('.rp-toc-state').textContent=state.visited[b.id]?'✓':''}})}
function updateSim(el){const out=el.querySelector('.rp-sim-result'),val=id=>Number(el.querySelector('#rp-'+id).value);el.querySelectorAll('input[type=range]').forEach(x=>{const o=el.querySelector('#'+x.id+'-val');if(o)o.textContent=x.value+x.dataset.unit});if(el.dataset.sim==='pv'){const rate=val('pv-rate')/100,N=val('pv-years'),m=val('pv-m'),pv=5e6/(1+rate/m)**(m*N),effective=(1+rate/m)**m-1;const rates=[0,3,6,9,12,15],values=rates.map(r=>5/(1+r/100/m)**(m*N));out.innerHTML=`<div class="rp-sim-numbers"><div><span>Present value</span><strong>CAD ${pv.toLocaleString('en-US',{maximumFractionDigits:2,minimumFractionDigits:2})}</strong></div><div><span>Effective annual rate</span><strong>${pct(effective)}</strong></div></div>${lineSVG([{name:'PV (CAD millions)',values}],{labels:rates.map(r=>r+'%'),yLabel:'PV (CAD millions)',min:0,max:5,xLabel:'Stated annual discount rate'})}`}else if(el.dataset.sim==='annual'){const R=val('ann-return')/100,d=val('ann-days');out.innerHTML=`<div class="rp-sim-numbers"><div><span>Annualization exponent</span><strong>${(365/d).toFixed(3)}</strong></div><div><span>Annualized return</span><strong>${pct((1+R)**(365/d)-1)}</strong></div></div>`}else{const R=val('lev-return')/100,c=val('lev-cost')/100,d=val('lev-debt')/100,ratio=d/(1-d),r=R+ratio*(R-c),ds=[0,20,40,60,80],vs=ds.map(x=>(R+(x/100)/(1-x/100)*(R-c))*100);out.innerHTML=`<div class="rp-sim-numbers"><div><span>Debt/equity</span><strong>${ratio.toFixed(3)}×</strong></div><div><span>Leveraged equity return</span><strong>${pct(r)}</strong></div></div>${lineSVG([{name:'Leveraged return',values:vs},{name:'Unlevered return',values:ds.map(()=>R*100)}],{labels:ds.map(x=>x+'%'),yLabel:'Equity return (%)',format:'pct',xLabel:'Debt / total assets'})}<p class="rp-muted">${R>c?'Positive return spread: borrowing raises return.':R<c?'Negative return spread: borrowing lowers return.':'Zero return spread: borrowing does not change return.'}</p>`}}
function jump(id,focus=true){const el=document.getElementById(id);if(!el)return;el.scrollIntoView({block:'start',behavior:'auto'});const b=el.closest('[data-rp-block]')||el;if(b.dataset.rpBlock){state.last=b.dataset.rpBlock;persist();host.querySelectorAll('.rp-toc button[data-rp-jump]').forEach(x=>x.classList.toggle('current',x.dataset.rpJump==='rp-b-'+b.dataset.rpBlock))}if(focus){el.setAttribute('tabindex','-1');el.focus({preventScroll:true})}}
function mode(v){state.mode=v;host.dataset.language=v;persist();host.querySelector('#rp-lang').value=v;host.querySelectorAll('.rp-vtoggle').forEach(btn=>{const b=D.blocks.find(b=>b.id===btn.dataset.rpVi);const open=v==='full'||stored(b);btn.setAttribute('aria-expanded',String(open));btn.textContent=open?'Hide Vietnamese':'Show Vietnamese explanation';btn.hidden=v!=='support'});host.querySelectorAll('.rp-feedback-vi').forEach(d=>d.open=v==='full')}
function render(root,part){host=root;host.classList.add('rp-host');host.innerHTML=`<div class="rp-page"><header class="rp-header"><div class="rp-crumb"><a href="#study">Learn</a><span> / </span><a href="#subject/01">Quantitative Methods</a><span> / LM1</span></div><div class="rp-header-row"><div><p class="rp-eyebrow">CFA LEVEL I · 2026 / LEARNING MODULE 1</p><h1>Rates and Returns</h1><p class="rp-sub">Understand interest rates, choose return measures and evaluate investment performance.</p></div><div class="rp-toolbar"><label>Language<select id="rp-lang"><option value="en">English Only</option><option value="support">English + Vietnamese Support</option><option value="full">English + Full Vietnamese</option></select></label><button type="button" class="rp-btn" data-rp-focus aria-pressed="false">Focus mode</button></div></div><div class="rp-overview"><div><strong>Learning objectives</strong><p>5 LOS · 8 linked learning blocks · 13 source-adapted checks</p></div><div class="rp-progress"><div class="rp-progress-text"></div><div class="rp-progress-track" role="progressbar" aria-label="Blocks studied" aria-valuemin="0" aria-valuemax="8" aria-valuenow="0"><div class="rp-progress-fill"></div></div></div></div><p class="rp-storage" hidden>Browser storage is unavailable; progress may be lost on reload.</p><details class="rp-objectives rp-detail"><summary>View all five learning outcomes (CFAI 2026, PDF p. 11)</summary><ol>${D.objectives.map(x=>`<li><strong>${esc(x[0])}</strong> ${esc(x[1])}</li>`).join('')}</ol></details></header><div class="rp-layout"><aside class="rp-sidebar"><details class="rp-toc" open><summary>Contents</summary>${D.blocks.map((b,i)=>`<button type="button" data-rp-jump="rp-b-${b.id}" ${state.last===b.id?'class="current"':''}><span>${i+1}.</span><span>${esc(b.title)}</span><span class="rp-toc-state">${state.visited[b.id]?'✓':''}</span></button>`).join('')}<button data-rp-jump="rp-review">Review results</button><button data-rp-jump="rp-source">Source references</button></details><div class="rp-side-help"><button type="button" class="rp-btn" data-rp-resume>Continue learning</button><a href="#module/${D.module}/questions/0">Open Question Bank →</a></div></aside><article class="rp-article">${D.blocks.map(block).join('')}${review()}${sourcePanel()}</article></div></div>`;mode(['en','support','full'].includes(state.mode)?state.mode:'support');host.querySelectorAll('[data-sim]').forEach(updateSim);status();if(part&&part!=='0'&&part!=='legacy'){const id=part==='resume'?'rp-b-'+(state.last||'rates'):/^\d+$/.test(part)?'rp-c-'+part:part.startsWith('rp-')?part:'rp-b-'+part;requestAnimationFrame(()=>jump(id,false))}else if(state.last&&state.last!=='rates'){/* Continue button restores the saved location, initial view stays at the beginning. */}}
function cleanup(root){root.classList.remove('rp-host');root.removeAttribute('data-language');document.body.classList.remove('rp-focus');host=null}
function click(e){if(!host||!host.classList.contains('rp-host'))return;const btn=e.target.closest('button,a');if(!btn||!host.contains(btn))return;let d=btn.dataset;if(d.rpResume!==undefined){jump('rp-b-'+(state.last||'rates'));return}if(d.rpJump){e.preventDefault();jump(d.rpJump);return}if(d.rpFocus!==undefined){const active=document.body.classList.toggle('rp-focus');btn.setAttribute('aria-pressed',String(active));btn.textContent=active?'Exit focus mode':'Focus mode';return}if(d.rpVi){state.explanations[d.rpVi]=!state.explanations[d.rpVi];persist();btn.closest('.rp-block').querySelector('.rp-concepts').classList.toggle('rp-expanded',!!state.explanations[d.rpVi]);btn.closest('.rp-block').classList.toggle('rp-expanded-block',!!state.explanations[d.rpVi]);btn.textContent=state.explanations[d.rpVi]?'Hide Vietnamese':'Show Vietnamese explanation';btn.setAttribute('aria-expanded',String(!!state.explanations[d.rpVi]));return}if(d.rpRead){state.visited[d.rpRead]=!state.visited[d.rpRead];state.last=d.rpRead;persist();btn.textContent=state.visited[d.rpRead]?'Reviewed ✓':'Mark as studied';status();return}if(d.rpSave){state.saved[d.rpSave]=!state.saved[d.rpSave];persist();btn.textContent=state.saved[d.rpSave]?'Saved ✓':'Save question';btn.setAttribute('aria-pressed',String(!!state.saved[d.rpSave]));status();return}if(d.rpQ){const q=find(d.rpQ);if(!q||state.attempts[q.n])return;const choice=Number(d.rpChoice);state.attempts[q.n]={choice,at:new Date().toISOString()};const b=D.blocks.find(b=>b.checks.includes(q.n));state.last=b.id;persist();btn.closest('.rp-question').outerHTML=question(q.n);host.querySelector('#rp-q-'+q.n+' .rp-feedback-vi').open=state.mode==='full';status();return}if(d.rpRetry){delete state.attempts[d.rpRetry];persist();btn.closest('.rp-question').outerHTML=question(Number(d.rpRetry));status();return}}
document.addEventListener('click',click);document.addEventListener('change',e=>{if(!host||!host.contains(e.target))return;if(e.target.id==='rp-lang')mode(e.target.value);else if(e.target.closest('[data-sim]'))updateSim(e.target.closest('[data-sim]'))});document.addEventListener('input',e=>{if(host&&host.contains(e.target)&&e.target.matches('input[type=range]')&&e.target.closest('[data-sim]'))updateSim(e.target.closest('[data-sim]'))});
function search(q){q=String(q||'').toLowerCase().trim();if(!q)return [];return D.blocks.filter(b=>[b.title,b.why,b.recognition,b.support,...b.rows.map(i=>R.coverageAudit.rows[i].title+' '+R.coverageAudit.rows[i].en),...b.formulas.map(i=>R.formulas[i][0]+' '+R.formulas[i][1])].join(' ').toLowerCase().includes(q)).map(b=>({title:b.title,url:a(b.id),los:b.los}))}
let scrollFrame=0;window.addEventListener('scroll',()=>{if(!host||scrollFrame)return;scrollFrame=requestAnimationFrame(()=>{scrollFrame=0;if(!host)return;const boxes=[...host.querySelectorAll('[data-rp-block]')],current=boxes.find(el=>{const r=el.getBoundingClientRect();return r.top<=160&&r.bottom>160});if(current&&state.last!==current.dataset.rpBlock){state.last=current.dataset.rpBlock;persist();host.querySelectorAll('.rp-toc button[data-rp-jump]').forEach(x=>x.classList.toggle('current',x.dataset.rpJump==='rp-b-'+state.last))}})},{passive:true});window.CFA_RATES_PROTOTYPE={render,cleanup,search,stats,reviewURL:a('rp-review')};
})();
